    private val slices = listOf(
        Triple("alice29.txt", alice, 0xe2be45e7L),
        Triple("sum", sparcBinary, 0x37aa0cbbL),
        Triple("kennedy.xls", spreadsheet, 0xd47cabeaL),
        Triple("fields.c", cSource, 0x4f618664L),
    )

    @Test
    fun slicesAreIntact() {
        for ((name, data, crc) in slices) assertEquals(crc, Crc32.of(data), name)
    }

    @Test
    fun everyEncoderRoundTripsAndCompresses() {
        for (id in Codecs.implemented) {
            val codec = Codecs.byId(id)!!
            for ((name, data, _) in slices) {
                val encoded = codec.compress(data)
                assertContentEquals(data, codec.decompress(encoded, ArchiveLimits.UNBOUNDED), "$id $name")
                if (id != CodecId.STORE && id != CodecId.SNAPPY) {
                    assertTrue(encoded.size < data.size, "$id did not compress $name: ${encoded.size} >= ${data.size}")
                }
            }
        }
    }

    @Test
    fun deflateLevelsAndWindowsRoundTrip() {
        for ((name, data, _) in slices) for (level in 0..9) for (windowBits in listOf(9, 15)) {
            val options = DeflateOptions { this.level = level; this.windowBits = windowBits }
            assertContentEquals(data, Inflate.inflate(Deflate.encode(data, options)), "$name $options")
        }
    }
}
